// CSD_RATIONALE_BEGIN
// This strategy generates a response for first-order logic reasoning problems. 
// It starts by generating tokens unconstrainedly until it encounters the start marker "<<". 
// Upon encountering "<<", it switches to constrained mode, ensuring that only valid next tokens according to the parser's grammar are generated. 
// If a completion marker ">>" is encountered during constrained mode, the process stops and the response is considered complete.
// CSD_RATIONALE_END

generated := [];
var steps: nat := 0;
var insideConstrained: bool := false;
var currentConstrained: Prefix := [];

while steps < maxSteps
  invariant 0 <= steps <= maxSteps
  invariant |generated| == steps
  invariant helpers.cost == steps
  invariant lm.ValidTokensIdsLogits()
  invariant insideConstrained ==> parser.IsValidPrefix(currentConstrained)
  invariant insideConstrained ==> forall t: Token :: t in parser.ValidNextTokens(currentConstrained) ==> t in lm.Tokens
  decreases maxSteps - steps, if insideConstrained then 1 else 0
{
  if !insideConstrained {
    // UNCONSTRAINED PHASE: choose HOW to generate the next unconstrained token
    // You may use helpers.UnconstrainedStep, or Pattern A (GenerateLogits + ChooseNextToken)
    // You may penalize or boost tokens using BoostTokenLogits/PenalizeTokenLogits
    var next := helpers.UnconstrainedStep(lm, prompt, generated);
    if next == eosToken { break; }
    generated := generated + [next];
    steps := steps + 1;
    if Contains(next, "<<") {
      insideConstrained := true;
      currentConstrained := [];
      CSDHelpers.RollbackPreservesTokenInvariant(lm, parser, []);
    }
  } else {
    if parser.IsCompletePrefix(currentConstrained) {
      insideConstrained := false;
    } else {
      // CONSTRAINED PHASE: choose HOW to generate the next constrained token
      // You may use ConstrainedStep, PenalizedConstrainedStep, BoostedConstrainedStep, SoftConstrainedStep, ConfidenceGatedStep
      var next := helpers.ConstrainedStep(lm, parser, prompt, currentConstrained);
      generated := generated + [next];
      currentConstrained := currentConstrained + [next];
      steps := steps + 1;

